{
  "name": "oceanai-certificate-console",
  "version": "1.0.0",
  "private": true,
  "type": "module",
  "description": "Multi-tenant certificate admin console (technical interview assessment)",
  "scripts": {
    "start": "node server/scripts/setup.js && vite build && node server/index.js",
    "dev": "node server/scripts/setup.js && vite",
    "build": "vite build",
    "setup": "node server/scripts/setup.js",
    "verify": "node server/scripts/verify.js",
    "seed:100k": "node server/scripts/seed-bulk.js",
    "test": "npm run verify"
  },
  "dependencies": {
    "better-sqlite3": "^11.9.1",
    "express": "^4.21.2"
  },
  "devDependencies": {
    "@vitejs/plugin-vue": "^5.2.1",
    "vite": "^6.2.0",
    "vue": "^3.5.13"
  }
}

import { defineConfig } from 'vite';
import vue from '@vitejs/plugin-vue';

export default defineConfig({
  root: 'web',
  plugins: [vue()],
  build: {
    outDir: '../dist',
    emptyOutDir: true,
  },
  server: {
    port: 5173,
    proxy: {
      '/api': 'http://localhost:3000',
    },
  },
});

import Database from 'better-sqlite3';
import fs from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';

const SCHEMA = `
CREATE TABLE IF NOT EXISTS tenants (
  id INTEGER PRIMARY KEY,
  slug TEXT UNIQUE NOT NULL,
  tz TEXT NOT NULL
);
CREATE TABLE IF NOT EXISTS admins (
  id INTEGER PRIMARY KEY,
  tenant_id INTEGER NOT NULL REFERENCES tenants(id),
  email TEXT UNIQUE NOT NULL
);
CREATE TABLE IF NOT EXISTS learners (
  id INTEGER PRIMARY KEY,
  tenant_id INTEGER NOT NULL REFERENCES tenants(id),
  name TEXT NOT NULL
);
CREATE TABLE IF NOT EXISTS courses (
  id INTEGER PRIMARY KEY,
  tenant_id INTEGER NOT NULL REFERENCES tenants(id),
  title TEXT NOT NULL
);
CREATE TABLE IF NOT EXISTS enrollments (
  id INTEGER PRIMARY KEY,
  tenant_id INTEGER NOT NULL REFERENCES tenants(id),
  course_id INTEGER NOT NULL REFERENCES courses(id),
  learner_id INTEGER NOT NULL REFERENCES learners(id),
  status TEXT NOT NULL CHECK (status IN ('completed','incomplete')),
  UNIQUE (course_id, learner_id)
);
CREATE TABLE IF NOT EXISTS certificates (
  id INTEGER PRIMARY KEY,
  tenant_id INTEGER NOT NULL REFERENCES tenants(id),
  course_id INTEGER NOT NULL REFERENCES courses(id),
  learner_id INTEGER NOT NULL REFERENCES learners(id),
  serial TEXT UNIQUE NOT NULL,
  issued_at_utc INTEGER NOT NULL,
  local_date TEXT NOT NULL,
  status TEXT NOT NULL DEFAULT 'active' CHECK (status IN ('active','revoked')),
  revoked_at_utc INTEGER,
  revoke_reason TEXT
);
CREATE INDEX IF NOT EXISTS idx_cert_tenant ON certificates(tenant_id);
CREATE INDEX IF NOT EXISTS idx_cert_local ON certificates(tenant_id, local_date);
CREATE INDEX IF NOT EXISTS idx_cert_serial ON certificates(serial);
CREATE TABLE IF NOT EXISTS audit_events (
  id INTEGER PRIMARY KEY,
  tenant_id INTEGER NOT NULL REFERENCES tenants(id),
  actor TEXT NOT NULL,
  cert_id INTEGER NOT NULL REFERENCES certificates(id),
  action TEXT NOT NULL CHECK (action IN ('issue','revoke')),
  at_utc INTEGER NOT NULL,
  reason TEXT
);
CREATE INDEX IF NOT EXISTS idx_audit_cert ON audit_events(cert_id, action);
CREATE TABLE IF NOT EXISTS idempotency_keys (
  id INTEGER PRIMARY KEY,
  tenant_id INTEGER NOT NULL REFERENCES tenants(id),
  key TEXT NOT NULL,
  request_hash TEXT NOT NULL,
  state TEXT NOT NULL DEFAULT 'running' CHECK (state IN ('running','done','error')),
  result_json TEXT,
  created_at INTEGER NOT NULL,
  updated_at INTEGER NOT NULL,
  UNIQUE (tenant_id, key)
);
CREATE TABLE IF NOT EXISTS serial_counters (
  tenant_id INTEGER NOT NULL REFERENCES tenants(id),
  year INTEGER NOT NULL,
  last_seq INTEGER NOT NULL,
  PRIMARY KEY (tenant_id, year)
);
`;

export function defaultDbPath() {
  const here = path.dirname(fileURLToPath(import.meta.url));
  return path.join(here, 'data.db');
}

export function openDb(dbPath = process.env.DB_PATH || defaultDbPath()) {
  if (dbPath !== ':memory:') fs.mkdirSync(path.dirname(dbPath), { recursive: true });
  const db = new Database(dbPath);
  db.pragma('journal_mode = WAL');
  db.pragma('foreign_keys = ON');
  db.pragma('busy_timeout = 5000');
  db.exec(SCHEMA);
  return db;
}

export function closeDb(db) {
  try { db.close(); } catch { /* already closed */ }
}

// Tenant-local timezone formatting and serial reservation helpers.

const DATE_FORMATS = {
  date: new Intl.DateTimeFormat('en-CA', { timeZone: 'UTC', year: 'numeric', month: '2-digit', day: '2-digit' }),
  partsFull: new Intl.DateTimeFormat('en-US', {
    timeZone: 'UTC',
    year: 'numeric', month: '2-digit', day: '2-digit',
    hour: '2-digit', minute: '2-digit', hourCycle: 'h23',
  }),
};

function fmt(parts, keys) {
  const out = {};
  for (const p of parts) out[p.type] = p.value;
  return keys.map((k) => out[k]).join('-');
}

// Returns YYYY-MM-DD calendar date of `utcMs` in the given IANA timezone.
export function tenantLocalDate(utcMs, tz) {
  const dtf = new Intl.DateTimeFormat('en-US', {
    timeZone: tz,
    year: 'numeric', month: '2-digit', day: '2-digit',
  });
  return fmt(dtf.formatToParts(new Date(utcMs)), ['year', 'month', 'day']);
}

// Returns { date: 'YYYY-MM-DD', time: 'HH:mm' } in the tenant timezone.
export function tenantLocalDateTime(utcMs, tz) {
  const dtf = new Intl.DateTimeFormat('en-US', {
    timeZone: tz,
    year: 'numeric', month: '2-digit', day: '2-digit',
    hour: '2-digit', minute: '2-digit', hourCycle: 'h23',
  });
  const p = {};
  for (const part of dtf.formatToParts(new Date(utcMs))) p[part.type] = part.value;
  return { date: `${p.year}-${p.month}-${p.day}`, time: `${p.hour}:${p.minute}` };
}

export function tenantLocalYear(utcMs, tz) {
  const dtf = new Intl.DateTimeFormat('en-US', { timeZone: tz, year: 'numeric' });
  return Number(dtf.format(new Date(utcMs)));
}

// Reserve `n` serial numbers for (tenant, year). Must be called inside a transaction.
export function reserveSerials(db, tenantId, year, n, slug) {
  const upd = db.prepare(
    `INSERT INTO serial_counters(tenant_id, year, last_seq) VALUES (?, ?, ?)
     ON CONFLICT(tenant_id, year) DO UPDATE SET last_seq = serial_counters.last_seq + ?
     RETURNING last_seq`
  );
  const { last_seq } = upd.get(tenantId, year, n, n);
  const seqs = [];
  for (let s = last_seq - n + 1; s <= last_seq; s++) seqs.push(`${slug}-${year}-${String(s).padStart(6, '0')}`);
  return seqs;
}

// CSV field escaping per RFC 4180.
export function csvField(value) {
  const s = value == null ? '' : String(value);
  return /[",\r\n]/.test(s) ? `"${s.replace(/"/g, '""')}"` : s;
}

export function hashRequest(obj) {
  const crypto = await import('node:crypto');
  return crypto.createHash('sha256').update(JSON.stringify(obj)).digest('hex');
}

