import { pathToFileURL } from 'node:url';
import { openDb, closeDb } from '../db.js';
import { tenantLocalDate, tenantLocalYear, reserveSerials } from '../helpers.js';
import { setup } from './setup.js';

// Generates `--count` certificate rows for one tenant (default east) without
// touching the quick-start demo dataset. Also creates matching learners and
// completed enrollments so the rows are joined cleanly in list/export.
export function seedBulk(dbPath, { tenant = 'east', count = 100000 } = {}) {
  const db = openDb(dbPath);
  const { seeded } = setup(db);
  if (seeded) console.log('(demo data seeded first)');

  const tenantId = db.prepare(`SELECT id, slug, tz FROM tenants WHERE slug = ?`).get(tenant);
  if (!tenantId) throw new Error(`unknown tenant slug: ${tenant}`);

  const course = db.prepare(`SELECT id, title FROM courses WHERE tenant_id = ? AND title = 'Safety 101'`).get(tenantId.id)
    || db.prepare(`SELECT id, title FROM courses WHERE tenant_id = ? ORDER BY id LIMIT 1`).get(tenantId.id);
  if (!course) throw new Error(`no course found for tenant ${tenant}`);

  const now = Date.now();
  const localDate = tenantLocalDate(now, tenantId.tz);
  const year = tenantLocalYear(now, tenantId.tz);

  const tx = db.transaction(() => {
    const insLearner = db.prepare(`INSERT INTO learners(tenant_id, name) VALUES (?, ?) RETURNING id`);
    const insEnroll = db.prepare(
      `INSERT INTO enrollments(tenant_id, course_id, learner_id, status) VALUES (?, ?, ?, 'completed')`
    );
    const insCert = db.prepare(
      `INSERT INTO certificates(tenant_id, course_id, learner_id, serial, issued_at_utc, local_date, status)
       VALUES (?, ?, ?, ?, ?, ?, 'active')`
    );

    const serials = reserveSerials(db, tenantId.id, year, count, tenantId.slug);

    for (let i = 0; i < count; i++) {
      const name = `Bulk Learner-${String(i + 1).padStart(6, '0')}`;
      const lid = insLearner.get(tenantId.id, name).id;
      insEnroll.run(tenantId.id, course.id, lid);
      insCert.run(tenantId.id, course.id, lid, serials[i], now, localDate);
    }
  });

  const t0 = Date.now();
  tx();
  const secs = ((Date.now() - t0) / 1000).toFixed(1);
  console.log(`inserted ${count} certificate rows for tenant '${tenant}' in ${secs}s (local_date ${localDate})`);
  closeDb(db);
}

if (import.meta.url === pathToFileURL(process.argv[1]).href) {
  const args = process.argv.slice(2);
  const getArg = (name, def) => {
    const i = args.indexOf(name);
    return i >= 0 ? args[i + 1] : def;
  };
  seedBulk(null, { tenant: String(getArg('--tenant', 'east')), count: Number(getArg('--count', 100000)) });
}

import { createApp } from 'vue';
import App from './App.vue';
import './style.css';

createApp(App).mount('#app');

let actor = null;

export function setActor(email) {
  actor = email;
}
export function getActor() {
  return actor;
}

async function req(path, opts = {}) {
  const headers = { ...(opts.headers || {}) };
  if (actor) headers['X-User'] = actor;
  const res = await fetch('/api' + path, { ...opts, headers });
  if (!res.ok) {
    let msg = `HTTP ${res.status}`;
    try {
      const j = await res.json();
      if (j.error) msg = j.error;
    } catch {
      /* non-JSON */
    }
    const err = new Error(msg);
    err.status = res.status;
    throw err;
  }
  return res.json();
}

export const api = {
  schema: () => req('/schema'),
  list: (p) => req('/certs?' + new URLSearchParams(p)),
  detail: (id) => req('/certs/' + id),
  bulk: (courseId, key) =>
    req('/certs/bulk', {
      method: 'POST',
      headers: { 'content-type': 'application/json', 'idempotency-key': key },
      body: JSON.stringify({ courseId }),
    }),
  revoke: (id, reason) =>
    req(`/certs/${id}/revoke`, {
      method: 'POST',
      headers: { 'content-type': 'application/json' },
      body: JSON.stringify(reason ? { reason } : {}),
    }),
};

export async function downloadCsv(params) {
  const headers = {};
  if (actor) headers['X-User'] = actor;
  const res = await fetch('/api/certs/export?' + new URLSearchParams(params), { headers });
  if (!res.ok) throw new Error(`export failed (HTTP ${res.status})`);
  const blob = await res.blob();
  const url = URL.createObjectURL(blob);
  const a = document.createElement('a');
  a.href = url;
  a.download = 'certificates.csv';
  document.body.appendChild(a);
  a.click();
  a.remove();
  URL.revokeObjectURL(url);
}

:root {
  --bg: #f4f5f7;
  --panel: #ffffff;
  --text: #1f2430;
  --muted: #6b7280;
  --line: #e5e7eb;
  --primary: #2563eb;
  --primary-dark: #1d4ed8;
  --danger: #dc2626;
  --ok: #059669;
  --warn: #d97706;
}
* { box-sizing: border-box; }
body {
  margin: 0;
  font-family: -apple-system, "Segoe UI", Roboto, "Helvetica Neue", Arial, sans-serif;
  background: var(--bg);
  color: var(--text);
  font-size: 14px;
  line-height: 1.5;
}
.app { max-width: 1080px; margin: 0 auto; padding: 16px 20px 48px; }
header.app-header {
  display: flex; align-items: center; justify-content: space-between;
  gap: 16px; flex-wrap: wrap;
  border-bottom: 1px solid var(--line); padding-bottom: 12px; margin-bottom: 20px;
}
header.app-header h1 { font-size: 18px; margin: 0; }
.actor-box {
  display: flex; align-items: center; gap: 8px;
  background: var(--panel); border: 1px solid var(--line);
  border-radius: 8px; padding: 6px 10px;
}
.actor-box label { color: var(--muted); font-size: 12px; }
.actor-box select { border: none; background: none; font-size: 14px; color: var(--text); outline: none; }
.actor-box .tenant { font-size: 12px; color: var(--muted); }

main.mini { margin-top: 20px; }
.back { background: var(--panel); border: 1px solid var(--line); border-radius: 6px; padding: 6px 12px; cursor: pointer; margin-bottom: 12px; }

.panel { background: var(--panel); border: 1px solid var(--line); border-radius: 10px; padding: 16px; margin-bottom: 16px; }
.panel h2 { margin: 0 0 12px; font-size: 15px; }
.section-note { color: var(--muted); font-size: 12px; }

.toolbar { display: flex; gap: 10px; align-items: center; flex-wrap: wrap; }
input[type="text"], input[type="number"], select {
  border: 1px solid var(--line); border-radius: 6px; padding: 7px 10px;
  font-size: 14px; background: #fff; color: var(--text);
}
input:focus, select:focus { outline: 2px solid var(--primary); outline-offset: 0; }

button {
  border: none; border-radius: 6px; padding: 7px 14px; font-size: 13px;
  cursor: pointer; background: var(--primary); color: #fff;
}
button:hover { background: var(--primary-dark); }
button:disabled { opacity: 0.5; cursor: not-allowed; }
button.ghost { background: var(--panel); color: var(--primary); border: 1px solid var(--primary); }
button.danger { background: var(--danger); }
button.ghost-danger { background: var(--panel); color: var(--danger); border: 1px solid var(--danger); }

table { width: 100%; border-collapse: collapse; }
th, td { text-align: left; padding: 8px 10px; border-bottom: 1px solid var(--line); }
th { font-size: 12px; text-transform: uppercase; color: var(--muted); cursor: pointer; user-select: none; }
th .arrow { color: var(--primary); }
th:hover { color: var(--text); }
tr.clickable { cursor: pointer; }
tr.clickable:hover { background: #f8fafc; }

.state-loading { color: var(--muted); padding: 24px; text-align: center; }
.state-empty { color: var(--muted); padding: 24px; text-align: center; }
.state-error {
  color: var(--danger); background: #fef2f2; border: 1px solid #fecaca;
  border-radius: 8px; padding: 12px 16px; margin: 12px 0;
  display: flex; justify-content: space-between; align-items: center; gap: 12px;
}

.status-tag { display: inline-block; border-radius: 999px; padding: 2px 10px; font-size: 12px; font-weight: 600; }
.status-active { background: #ecfdf5; color: var(--ok); }
.status-revoked { background: #fef2f2; color: var(--danger); }

.pagination { display: flex; align-items: center; gap: 10px; margin-top: 12px; color: var(--muted); }
.pagination button { background: var(--panel); border: 1px solid var(--line); color: var(--text); }

.bulk-result { margin-top: 12px; border-top: 1px solid var(--line); padding-top: 12px; }
.outcome-issued { color: var(--ok); }
.outcome-skipped { color: var(--warn); }

dl.detail { display: grid; grid-template-columns: 160px 1fr; gap: 8px 16px; }
dl.detail dt { color: var(--muted); }
dl.detail dd { margin: 0; }

.modal-backdrop {
  position: fixed; inset: 0; background: rgba(0,0,0,.35);
  display: flex; align-items: center; justify-content: center; z-index: 10;
}
.modal { background: #fff; border-radius: 10px; padding: 20px; width: 420px; max-width: 92vw; }
.modal h3 { margin: 0 0 10px; }
.modal-actions { display: flex; justify-content: flex-end; gap: 10px; margin-top: 16px; }

.meta { color: var(--muted); font-size: 12px; margin-top: 8px; }

